   LOADER SHAPE: ONE loader for this vault table; each run is a SEPARATE feed
   tagged by RECORD_SOURCE and SOURCE_RUN. RECORD_SOURCE is NEVER in the key.
   KEY FORM: md5(upper('HUB_FINANCIAL_TRANSACTION|' || <business key>)), emitted EXPLICITLY -- no macro computes a
   hash in this build. The namespace is a MEASURED collision guard: opus_health_v2 emits
   md5(upper(HUB_ASSESSMENT_BK__SCRUTINY_NO)) AND md5(upper(HUB_PROPOSAL_BK__SCRUTINY_NO)),
   the same column under two hubs, which collide without it; legacy namespaces 1822 of 1822.
   CRITICAL PRECISION: the namespace separates HUBS, NOT REGISTRIES WITHIN A HUB.
   'HUB_POLICY|' prefixes POLICY_REF and POLICY_NO identically, so it does nothing to keep
   two identifier populations inside one hub apart.
   REGISTRY RECONCILIATION, UNRESOLVED: unifying the hash form does NOT establish that the
   two runs' identifier spaces denote the same entities. 6 of the 14 shared hubs have ZERO
   business-key-column overlap between the runs. This hub is ONE KEY SPACE over the
   registries enumerated below; a false merge is unrecoverable after load.
     opus_health_delta3       1 registry/registries: HUB_FINANCIAL_TRANSACTION_BK__TRANSACTION_ID
     opus_health_legacy_v4    3 registry/registries: HUB_FINANCIAL_TRANSACTION_BK__PTRANSACTION_ID, HUB_FINANCIAL_TRANSACTION_BK__TPA_TRANS_KEY, HUB_FINANCIAL_TRANSACTION_BK__UTR_NO
*/

with feeds as (
    select HUB_FINANCIAL_TRANSACTION_HK, HUB_FINANCIAL_TRANSACTION_BK__PTRANSACTION_ID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_financial_transaction__health_webservice_info__c6c1b7987c') }}
    union all
    select HUB_FINANCIAL_TRANSACTION_HK, HUB_FINANCIAL_TRANSACTION_BK__UTR_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_financial_transaction__hm_hcm_extract__526f9c3610') }}
    union all
    select HUB_FINANCIAL_TRANSACTION_HK, HUB_FINANCIAL_TRANSACTION_BK__TRANSACTION_ID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_financial_transaction__policy_bases_extn__2eac9c0a47') }}
    union all
    select HUB_FINANCIAL_TRANSACTION_HK, HUB_FINANCIAL_TRANSACTION_BK__TRANSACTION_ID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_financial_transaction__starpkg_pol_dtls__eb2c4b34dd') }}
    union all
    select HUB_FINANCIAL_TRANSACTION_HK, HUB_FINANCIAL_TRANSACTION_BK__TPA_TRANS_KEY as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_financial_transaction__tpa_claim_details_ws__7e26a8f20c') }}
)

select
    HUB_FINANCIAL_TRANSACTION_HK,
    BUSINESS_KEY,
    min(RECORD_SOURCE) as RECORD_SOURCE,
    min(SOURCE_RUN) as SOURCE_RUN,
    min(LOAD_DATETIME) as LOAD_DATETIME
from feeds
where HUB_FINANCIAL_TRANSACTION_HK is not null
group by HUB_FINANCIAL_TRANSACTION_HK, BUSINESS_KEY
